/// Geodetic latitude, longitude [rad] and height of an Earth-fixed position on an ellipsoid of equatorial radius re
/// and flattening f.
/// - r: real[m][3] (passed in m)
/// - re: real[m] (passed in m)
/// - f: real[1] (passed a plain number)
/// - returns lat: real[1] (passed a plain number)
/// - returns lon: real[1] (passed a plain number)
/// - returns alt: real[m] (passed in m)
#[allow(clippy::too_many_arguments)]
pub fn geodetic_with(r: [f64; 3], re: f64, f: f64) -> (f64, f64, f64) {
    let mut lat: f64 = 0.0;
    let mut lon: f64 = 0.0;
    let mut alt: f64 = 0.0;
    let mut x: f64 = r[0];
    let mut y: f64 = r[1];
    let mut z: f64 = r[2];
    let mut e2: f64 = (f * (2.0 - f));
    lon = f64::atan2(y, x);
    let mut p: f64 = f64::hypot(x, y);
    let mut la: f64 = f64::atan2(z, (p * (1.0 - e2)));
    {
        let __end57: i64 = 5;
        let mut k: i64 = 0;
        while k < __end57 {
            let mut sph: f64 = f64::sin(la);
            let mut n: f64 = (re / f64::sqrt((1.0 - (e2 * rt::ipow(sph, 2)))));
            let mut al: f64 = ((p / f64::cos(la)) - n);
            la = f64::atan2(z, (p * (1.0 - ((e2 * n) / (n + al)))));
            k += 1;
        }
    }
    let mut sph2: f64 = f64::sin(la);
    let mut n2: f64 = (re / f64::sqrt((1.0 - (e2 * rt::ipow(sph2, 2)))));
    alt = ((p / f64::cos(la)) - n2);
    lat = la;
    (lat, lon, alt)
}

